<script setup lang="ts">
import {computed,ref} from 'vue';import type {Product,CartLine} from '../../../../packages/shared/src/types';import {money} from '../../../../packages/shared/src/domain';import Modal from '../../../../packages/ui/src/Modal.vue';import ProductPhoto from './ProductPhoto.vue';
const p=defineProps<{product:Product;initial?:CartLine}>();const emit=defineEmits<{close:[];add:[CartLine]}>();
const variant=ref(p.initial?.variantId??p.product.variants[0]?.id??'');const options=ref<string[]>([...(p.initial?.optionIds??[])]);const quantity=ref(p.initial?.quantity??1);const note=ref(p.initial?.note??'');
const price=computed(()=>(p.product.price+(p.product.variants.find(v=>v.id===variant.value)?.delta??0)+p.product.options.filter(o=>options.value.includes(o.id)).reduce((n,o)=>n+o.price,0))*quantity.value);
function add(){emit('add',{productId:p.product.id,variantId:variant.value,quantity:quantity.value,optionIds:options.value,note:note.value});emit('close')}
</script><template><Modal :title="product.name" @close="emit('close')"><ProductPhoto class="option-photo" :photo="product.photo" :image="product.image" :name="product.name"/><p class="muted">{{product.description}}</p><h3>Chọn size</h3><div class="choice-row"><label v-for="v in product.variants" :key="v.id" class="choice" :class="{selected:variant===v.id}"><input type="radio" v-model="variant" :value="v.id" name="size">{{v.name}}<small>{{v.delta?'+'+money(v.delta):'Tiêu chuẩn'}}</small></label></div><h3>Topping</h3><label v-for="o in product.options" :key="o.id" class="check-row"><input type="checkbox" v-model="options" :value="o.id"><span>{{o.name}}</span><b>+{{money(o.price)}}</b></label><label class="field"><span>Ghi chú pha chế</span><textarea v-model="note" maxlength="500" placeholder="Ít đá, ít đường..."></textarea></label><div class="action-row"><div class="stepper"><button @click="quantity=Math.max(1,quantity-1)" aria-label="Giảm số lượng">−</button><input aria-label="Số lượng món" type="number" min="1" max="99" v-model.number="quantity"><button @click="quantity=Math.min(99,quantity+1)" aria-label="Tăng số lượng">+</button></div><button class="btn primary" @click="add" :disabled="!Number.isInteger(quantity)||quantity<1||quantity>99">Thêm món · {{money(price)}}</button></div></Modal></template>
